#include <nlohmann/json.hpp>
#include <cstdint>
#include <iostream>
#include <string>

enum class book_id : std::uint64_t;
enum class small_signed : std::int8_t;
enum class small_unsigned : std::uint8_t;

using json = nlohmann::json;

int main()
{
    const book_id large_id{static_cast<book_id>(static_cast<std::uint64_t>(1) << 63)};
    const json j = large_id;
    if (!(j > 0u)) { std::cout << "FAIL: > 0u\n"; return 1; }
    if (nlohmann::to_string(j) != "9223372036854775808") { std::cout << "FAIL: to_string\n"; return 1; }
    if (!j.is_number_unsigned()) { std::cout << "FAIL: is_number_unsigned\n"; return 1; }

    const json jfull = book_id{static_cast<book_id>(0xFFFFFFFFFFFFFFFFULL)};
    if (!jfull.is_number_unsigned() || nlohmann::to_string(jfull) != "18446744073709551615") { std::cout << "FAIL: full range\n"; return 1; }

    const json js = small_signed{-2};
    if (!(js == -2) || !js.is_number_integer()) { std::cout << "FAIL: signed enum\n"; return 1; }

    const json ju = small_unsigned{255};
    if (!(ju == 255) || !ju.is_number_unsigned()) { std::cout << "FAIL: small unsigned enum\n"; return 1; }

    // round trip
    auto back = j.get<book_id>();
    if (static_cast<std::uint64_t>(back) != (static_cast<std::uint64_t>(1) << 63)) { std::cout << "FAIL: roundtrip\n"; return 1; }

    std::cout << "OK\n";
    return 0;
}

